// Changes: Behaviour of the background-animation pause: an explicit choice wins, otherwise reduced motion pauses.

import { describe, expect, it } from 'vitest'
import { isAnimationPaused, parseMotionChoice } from './motionPreference'

describe('animation pause', () => {
  it('follows the reduced-motion setting while the user has not chosen', () => {
    expect(isAnimationPaused(true, null)).toBe(true)
    expect(isAnimationPaused(false, null)).toBe(false)
  })

  it('lets an explicit choice override the system setting', () => {
    expect(isAnimationPaused(true, 'play')).toBe(false)
    expect(isAnimationPaused(false, 'pause')).toBe(true)
  })

  it('reads only known stored values', () => {
    expect(parseMotionChoice('pause')).toBe('pause')
    expect(parseMotionChoice('play')).toBe('play')
    expect(parseMotionChoice('yes')).toBeNull()
    expect(parseMotionChoice(null)).toBeNull()
  })
})
